class Solution:
    def countGoodNodes(self, edges: list[list[int]]) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        good_count = 0
        def dfs(u, p):
            nonlocal good_count
            sub_sizes = []
            total_size = 1
            for v in adj[u]:
                if v == p:
                    continue
                sz = dfs(v, u)
                sub_sizes.append(sz)
                total_size += sz
            if len(set(sub_sizes)) <= 1:
                good_count += 1
            return total_size

        dfs(0, -1)
        return good_count

class Solution {
public:
    int countGoodNodes(vector<vector<int>>& edges) {
        int n = edges.size() + 1;
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        int good_count = 0;
        auto dfs = [&](auto& self, int u, int p) -> int {
            int prev_sz = -1;
            bool is_good = true;
            int total_size = 1;
            for (int v : adj[u]) {
                if (v == p) continue;
                int sz = self(self, v, u);
                total_size += sz;
                if (prev_sz == -1) {
                    prev_sz = sz;
                } else if (prev_sz != sz) {
                    is_good = false;
                }
            }
            if (is_good) good_count++;
            return total_size;
        };
        dfs(dfs, 0, -1);
        return good_count;
    }
};

class Solution {
    private int goodCount = 0;
    public int countGoodNodes(int[][] edges) {
        int n = edges.length + 1;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        dfs(0, -1, adj);
        return goodCount;
    }

    private int dfs(int u, int p, List<List<Integer>> adj) {
        int prevSz = -1;
        boolean isGood = true;
        int totalSize = 1;
        for (int v : adj.get(u)) {
            if (v == p) continue;
            int sz = dfs(v, u, adj);
            totalSize += sz;
            if (prevSz == -1) {
                prevSz = sz;
            } else if (prevSz != sz) {
                isGood = false;
            }
        }
        if (isGood) goodCount++;
        return totalSize;
    }
}

